const fees = await fetch("https://ashtechpay.top/v1/fees", {
  headers: { "Authorization": "Bearer YOUR_API_KEY" }
}).then(r => r.json());

// Calculer le montant net credite sur votre compte
function computeNet(grossAmount, countryCode) {
  const fee = fees.find(f => f.country_code === countryCode);
  if (!fee) return grossAmount;
  const feeAmount = Math.round(grossAmount * fee.total_fee_pct / 100);
  return {
    gross: grossAmount,
    fee: feeAmount,
    net: grossAmount - feeAmount,
    fee_pct: fee.total_fee_pct,
  };
}

// Exemple :
console.log(computeNet(10000, "CM"));
// -> { gross: 10000, fee: 550, net: 9450, fee_pct: 5.5 }`,a,"javascript"),a=ja(s,"9. Webhooks",a),a=Xr(s,"Quand une transaction atteint un etat final, Ashtech Pay envoie automatiquement une requete POST a la notify_url passee dans votre appel a /v1/collect. Le champ amount correspond au montant net apres frais, et total_amount au montant brut collecte. Chaque livraison est dedupliquee, signee en HMAC-SHA256 et retentee automatiquement en cas d'echec temporaire.",a),a+=3,a=Rr(s,"Payload — paiement reussi",a),a=sr(s,`{
